CREATE TABLE IF NOT EXISTS user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000));
CREATE TABLE IF NOT EXISTS session (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000), ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON session(user_id);
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000), UNIQUE(provider_id, account_id));
CREATE INDEX IF NOT EXISTS account_user_idx ON account(user_id);
CREATE TABLE IF NOT EXISTS verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000));
CREATE INDEX IF NOT EXISTS verification_identifier_idx ON verification(identifier);
CREATE TABLE IF NOT EXISTS flary_installation (id TEXT PRIMARY KEY CHECK(id = 'owner'), status TEXT NOT NULL CHECK(status IN ('initializing','ready')), owner_user_id TEXT, created_at INTEGER NOT NULL, initialized_at INTEGER);
CREATE TABLE IF NOT EXISTS flary_connection (id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL, tenant_id TEXT NOT NULL, kind TEXT NOT NULL, label TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'needs_auth', encrypted_credential TEXT, credential_generation TEXT, credential_expires_at INTEGER, namespace TEXT, endpoint_url TEXT, transport TEXT, auth_type TEXT, metadata_json TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch() * 1000));
CREATE UNIQUE INDEX IF NOT EXISTS flary_connection_mcp_namespace_idx ON flary_connection(tenant_id, owner_user_id, namespace) WHERE kind = 'mcp' AND namespace IS NOT NULL;
CREATE TABLE IF NOT EXISTS flary_provider_oauth_session (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, user_id TEXT NOT NULL, connection_id TEXT NOT NULL, provider TEXT NOT NULL, method TEXT NOT NULL, status TEXT NOT NULL, authorization_url TEXT, verification_uri TEXT, user_code TEXT, interval_seconds INTEGER, private_state TEXT NOT NULL, expires_at INTEGER NOT NULL, account_subject TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS flary_provider_oauth_owner_idx ON flary_provider_oauth_session(tenant_id, user_id, created_at);
CREATE TABLE IF NOT EXISTS flary_mcp_oauth_session (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, user_id TEXT NOT NULL, connection_id TEXT NOT NULL, status TEXT NOT NULL, private_state TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS flary_mcp_oauth_owner_idx ON flary_mcp_oauth_session(tenant_id, user_id, created_at);
CREATE INDEX IF NOT EXISTS flary_mcp_oauth_connection_idx ON flary_mcp_oauth_session(connection_id, tenant_id, user_id);
